        void UpdateSelectedObjectToolbarMenu()
        {
            if (ContextToolbarMenuButton == null) return;

            var title = DataManager.SelectedIsResult ? "Result" : "Experiment";
            var menu = new NSMenu(title) { AutoEnablesItems = false };
            menu.AddItem(new NSMenuItem(title) { Hidden = true });

            if (DataManager.SelectedIsResult)
            {
                PopulateResultToolbarMenu(menu);
            }
            else
            {
                PopulateExperimentToolbarMenu(menu);
            }

            ContextToolbarMenuButton.Menu = menu;
            ContextToolbarMenuButton.Title = title;
            ContextToolbarMenuButton.SelectItem(0);
        }

        void UpdateWorkflowToolbarMenu()
        {
            if (WorkflowToolbarMenuButton == null
                || WorkflowToolbarItem == null
                || overviewDisplayControl == null) return;

            var title = StateManager.CurrentState switch
            {
                ProgramState.Load => "Overview",
                ProgramState.Process => "Processing",
                ProgramState.Analyze => "Analysis",
                ProgramState.AnalysisView => "Result View",
                _ => "Workflow",
            };

            var menu = new NSMenu(title) { AutoEnablesItems = false };
            menu.AddItem(new NSMenuItem(title) { Hidden = true });

            switch (StateManager.CurrentState)
            {
                case ProgramState.Load:
                    overviewDisplayControl.Enabled = DataManager.Current != null;
                    overviewDisplayControl.SelectedSegment =
                        ViewController.OverviewShowsInjections ? 1 : 0;
                    WorkflowToolbarItem.View = overviewDisplayControl;
                    break;
                case ProgramState.Process:
                    WorkflowToolbarMenuButton.Hidden = false;
                    WorkflowToolbarItem.View = WorkflowToolbarMenuButton;
                    PopulateProcessingToolbarMenu(menu);
                    break;
                case ProgramState.Analyze:
                    WorkflowToolbarMenuButton.Hidden = false;
                    WorkflowToolbarItem.View = WorkflowToolbarMenuButton;
                    PopulateAnalysisToolbarMenu(menu);
                    break;
                case ProgramState.AnalysisView:
                    WorkflowToolbarMenuButton.Hidden = false;
                    WorkflowToolbarItem.View = WorkflowToolbarMenuButton;
                    PopulateAnalysisResultToolbarMenu(menu);
                    break;
                default:
                    WorkflowToolbarItem.View = WorkflowToolbarMenuButton;
                    WorkflowToolbarMenuButton.Hidden = true;
                    break;
            }

            WorkflowToolbarMenuButton.Menu = menu;
            WorkflowToolbarMenuButton.Title = title;
            WorkflowToolbarMenuButton.SelectItem(0);
        }

        void PopulateExperimentToolbarMenu(NSMenu menu)
        {
            var hasData = DataManager.SelectedIsData && DataManager.Current != null;
            var hasAttributes = hasData && DataManager.Current.Attributes.Count > 0;
            var canRecalculateActualConcentrations = CanRecalculateActualConcentrations(DataManager.Current);

            menu.AddItem(CreateContextMenuItem("Details...", "openattributes", hasData, (s, e) => OpenCurrentExperimentAttributes()));
            menu.AddItem(CreateCopyAttributesMenuItem(hasAttributes));
            menu.AddItem(CreateCopyAttributeMenuItem(hasAttributes));
            menu.AddItem(CreateContextMenuItem("Clear attributes", "clearattributes", hasAttributes, (s, e) =>
            {
                var dataName = string.IsNullOrWhiteSpace(DataManager.Current.Name) ? DataManager.Current.FileName : DataManager.Current.Name;
                if (!ConfirmationDialog.ConfirmRemoveOrDelete(
                    "Confirm Clear Attributes",
                    $"Are you sure you wish to clear all attributes for {dataName}?",
                    "Clear Attributes")) return;

                DataManager.Current.ClearAttributes();
                UpdateContextToolbarMenu();
            }));
            if (hasData && DataManager.Current.DataSourceFormat == ITCDataFormat.IntegratedHeats)
            {
                menu.AddItem(NSMenuItem.SeparatorItem);
                menu.AddItem(CreateContextMenuItem("Recalculate actual concentrations", "recalculateactualconcentrations", canRecalculateActualConcentrations, (s, e) => RecalculateActualConcentrations(DataManager.Current)));
            }
            menu.AddItem(NSMenuItem.SeparatorItem);
            menu.AddItem(CreateContextMenuItem("Duplicate data", "duplicate", hasData, (s, e) => DataManager.DuplicateSelectedData(DataManager.Current)));
            menu.AddItem(CreateContextMenuItem("Export data...", "exportselecteddata", hasData, (s, e) => Exporter.Export(null, ExportDataSelection.SelectedData)));
            menu.AddItem(NSMenuItem.SeparatorItem);
            menu.AddItem(CreateContextMenuItem("Clear solution", "clearsolution", hasData && DataManager.Current.Solution != null, (s, e) =>
            {
                var dataName = string.IsNullOrWhiteSpace(DataManager.Current.Name) ? DataManager.Current.FileName : DataManager.Current.Name;
                if (!ConfirmationDialog.ConfirmRemoveOrDelete(
                    "Confirm Clear Solution",
                    $"Are you sure you wish to clear the fitted solution for {dataName}?",
                    "Clear Solution")) return;

                DataManager.Current.RemoveModel();
                UpdateContextToolbarMenu();
            }));
            menu.AddItem(CreateContextMenuItem("Remove data", "delete", hasData, (s, e) => DeleteSelectedItem()));
        }

