        void SetAnalysisResultErrorStyle(UncertaintyDisplayStyle style)
        {
            AppSettings.UncertaintyDisplayStyle = style;
            AppSettings.Save();
            AnalysisResultTabViewController.RequestDisplayRefresh();
            UpdateContextToolbarMenu();
        }

        void SetAnalysisResultTemperatureUnit(bool useKelvin)
        {
            AnalysisResultTabViewController.RequestTemperatureUnit(useKelvin);
            UpdateContextToolbarMenu();
        }

        NSMenuItem CreateCopyAttributesMenuItem(bool hasAttributes)
        {
            var item = CreateContextMenuItem("Copy all attributes", "copyattributes", hasAttributes, null);
            var submenu = new NSMenu("Copy all attributes") { AutoEnablesItems = false };
            var hasOtherExperiments = DataManager.Data.Any(data => data != DataManager.Current);
            var hasActiveTargets = DataManager.Data.Any(data => data != DataManager.Current && data.Include);

            submenu.AddItem(CreateContextMenuItem("All", "copyatttoall", hasAttributes && hasOtherExperiments, (s, e) => DataManager.CopySelectedAttributesToAll()));
            submenu.AddItem(CreateContextMenuItem("Active", "copyatttoactive", hasAttributes && hasActiveTargets, (s, e) => DataManager.CopySelectedAttributesToActive()));
            submenu.AddItem(NSMenuItem.SeparatorItem);
            submenu.AddItem(CreateContextMenuItem("Specific experiments:", null, false, null));

            var targets = DataManager.Data
                .Where(data => data != DataManager.Current)
                .OrderBy(data => data.Name)
                .ToList();

            if (targets.Count == 0)
            {
                submenu.AddItem(CreateContextMenuItem("No other experiments", null, false, null));
            }
            else
            {
                foreach (var experiment in targets)
                {
                    var target = experiment;
                    submenu.AddItem(CreateContextMenuItem(target.Name, "copyatttospecific", hasAttributes, (s, e) => DataManager.CopySelectedAttributesToExperiment(target)));
                }
            }

            item.Submenu = submenu;
            return item;
        }

        NSMenuItem CreateCopyAttributeMenuItem(bool hasAttributes)
        {
            var item = CreateContextMenuItem("Copy attribute", "copyattribute", hasAttributes, null);
            var submenu = new NSMenu("Copy attribute") { AutoEnablesItems = false };
            var source = DataManager.Current;
            var targets = DataManager.Data
                .Where(data => data != source)
                .OrderBy(data => data.Name)
                .ToList();
            var hasActiveTargets = targets.Any(data => data.Include);

            if (!hasAttributes || source == null)
            {
                item.Submenu = submenu;
                return item;
            }

            foreach (var attribute in source.Attributes)
            {
                var sourceAttribute = attribute;
                var title = AttributeCopyMenuTitle(sourceAttribute, source);
                var attributeItem = CreateContextMenuItem(title, null, true, null);
                var targetMenu = new NSMenu(title) { AutoEnablesItems = false };

                targetMenu.AddItem(CreateContextMenuItem("All", "copysingleattributetoall", targets.Count > 0,
                    (s, e) => DataManager.CopySelectedAttributeToAll(sourceAttribute)));
                targetMenu.AddItem(CreateContextMenuItem("Active", "copysingleattributetoactive", hasActiveTargets,
                    (s, e) => DataManager.CopySelectedAttributeToActive(sourceAttribute)));
                targetMenu.AddItem(NSMenuItem.SeparatorItem);
                targetMenu.AddItem(CreateContextMenuItem("Specific experiments:", null, false, null));

                if (targets.Count == 0)
                {
                    targetMenu.AddItem(CreateContextMenuItem("No other experiments", null, false, null));
                }
                else
                {
                    foreach (var experiment in targets)
                    {
                        var target = experiment;
                        targetMenu.AddItem(CreateContextMenuItem(target.Name, "copysingleattributetoexperiment", true,
                            (s, e) => DataManager.CopySelectedAttributeToExperiment(sourceAttribute, target)));
                    }
                }

                attributeItem.Submenu = targetMenu;
                submenu.AddItem(attributeItem);
            }

            item.Submenu = submenu;
            return item;
        }

        string AttributeCopyMenuTitle(ExperimentAttribute attribute, ExperimentData source)
        {
            var name = attribute.GetDisplayName();
            var value = attribute.GetDisplayValue(source);
            return string.IsNullOrWhiteSpace(value) ? name : $"{name}: {value}";
        }

        void OpenCurrentExperimentAttributes()
        {
            var data = DataManager.Current;
            if (data == null) return;

            ExperimentDetailsPopoverController.Data = data;

            var presenter = Window?.ContentViewController;
            var storyboard = presenter.Storyboard ?? NSStoryboard.FromName("Main", null);
            var controller = storyboard?.InstantiateControllerWithIdentifier("DetailsPopover") as ExperimentDetailsPopoverController;

            presenter.PresentViewControllerAsSheet(controller);
        }

        bool CanRecalculateActualConcentrations(ExperimentData data)
        {
            return data != null
                && data.DataSourceFormat == ITCDataFormat.IntegratedHeats
                && !data.IsTandemExperiment
                && data.Injections.Count > 0
                && data.CellVolume > double.Epsilon
                && (data.CellConcentration > double.Epsilon || data.SyringeConcentration > double.Epsilon);
        }

        void RecalculateActualConcentrations(ExperimentData data)
        {
            if (!CanRecalculateActualConcentrations(data)) return;

            RawDataReader.ProcessInjections(data);
            data.MarkModified();

            DataManager.InvokeUpdateDataViewCells();
            DataManager.InvokeUpdateTable();
            DataAnalysisViewController.InvalidateGraph();
            FinalFigureGraphView.Invalidate();
            UpdateContextToolbarMenu();
            StatusBarManager.SetStatus("Actual concentrations recalculated", 2000);
        }

        NSMenuItem CreateContextMenuItem(string title, string identifier, bool enabled, EventHandler activated, bool isChecked = false)
        {
            var item = new NSMenuItem(title)
            {
                Enabled = enabled,
                State = isChecked ? NSCellStateValue.On : NSCellStateValue.Off,
            };

            if (!string.IsNullOrEmpty(identifier)) item.Identifier = identifier;
            if (activated != null) item.Activated += activated;

            return item;
        }

        void SendActionToResponder(string selector)
        {
            NSApplication.SharedApplication.SendAction(new ObjCRuntime.Selector(selector), null, this);
        }

        void SetSelectedResultExperimentsActive()
        {
            var result = DataManager.SelectedResult;
            if (result == null) return;

            var solutionExperiments = result.Solution.Model.Models.Select(model => model.Data.UniqueID).ToList();
            foreach (var data in DataManager.Data)
            {
                data.Include = solutionExperiments.Contains(data.UniqueID);
            }

            DataManager.InvokeDataInclusionDidChange();
            UpdateContextToolbarMenu();
        }

        void LoadSelectedResultSolutionsToExperiments()
        {
            var result = DataManager.SelectedResult;
            if (result == null) return;

            StatusBarManager.SetStatus("Copying solutions to experiments...");

            DataManager.LoadResultSolutionsToExperiments(result);

            StatusBarManager.ClearAppStatus();
            StatusBarManager.SetStatus("Solutions updated", 2000);
            DataManager.InvokeUpdateDataViewCells();
            DataAnalysisViewController.InvalidateGraph();
            UpdateContextToolbarMenu();
        }

        async Task UpdateSelectedResult()
        {
            var result = DataManager.SelectedResult;
            if (result == null) return;

            var options = AnalysisResultUpdateOptions.StoredSettings;
            if (AnalysisResultUpdater.CanOverrideBootstrapIterations(result))
            {
                options = await PlatformServices.AnalysisResultUpdatePromptService
                    .ChooseOptionsAsync(result);
                if (options == null) return;
            }

            StatusBarManager.SetStatus("Updating analysis result...", 0, priority: 1);

            try
            {
                var convergence = await AnalysisResultUpdater.UpdateAsync(result, options);

                StatusBarManager.ClearAppStatus();
                StatusBarManager.QueueStatus("Analysis result updated", 3000);
                StatusBarManager.QueueStatus($"{convergence.Algorithm.GetProperties().ShortName} | RMSD = {convergence.Loss:G4}", 5000);
                var boundaryWarning = ParameterBoundaryWarningFormatter.Format(
                    convergence.ParameterBoundaryContacts);
                if (!string.IsNullOrWhiteSpace(boundaryWarning))
                    StatusBarManager.QueueStatus(boundaryWarning, 5000);

                DataManager.InvokeUpdateDataViewCells();
                DataManager.InvokeUpdateTable();
                DataAnalysisViewController.InvalidateGraph();
                FinalFigureGraphView.Invalidate();
                AnalysisResultTabViewController.RequestDisplayRefresh();
                UpdateContextToolbarMenu();
            }
            catch (Exception ex)
            {
                StatusBarManager.ClearAppStatus();
                AppEventHandler.DisplayHandledException(ex);
                UpdateContextToolbarMenu();
            }
        }

        bool CanExportSelectedResultFinalFigures()
        {
            var result = DataManager.SelectedResult;
            return result != null && result.IsValidForCurrentData;
        }

        void ExportSelectedResultFinalFigures()
        {
            var result = DataManager.SelectedResult;
            if (result == null) return;

            FinalFigureGraphView.Export(result);
        }

        void DeleteSelectedItem()
        {
            if (DataManager.SelectedContentIndex == -1) return;
            if (DataManager.SelectedContentIndex >= DataManager.SourceItems.Count) return;

            var item = DataManager.SourceItems[DataManager.SelectedContentIndex];
            var itemType = item is AnalysisResult ? "Result" : "Data";
            var itemName = string.IsNullOrWhiteSpace(item.Name) ? item.FileName : item.Name;

            if (!ConfirmationDialog.ConfirmRemoveOrDelete(
                $"Confirm Delete {itemType}",
                $"Are you sure you wish to delete {itemName}?",
                $"Delete {itemType}")) return;

            DataManager.RemoveSourceItemAt(DataManager.SelectedContentIndex);
            UpdateContextToolbarMenu();
        }

        void DeleteAllResults()
        {
            if (DataManager.Results.Count == 0) return;

            if (!ConfirmationDialog.ConfirmRemoveOrDelete(
                "Confirm Delete All Results",
                $"Are you sure you wish to delete all {DataManager.Results.Count} analysis results?",
                "Delete All Results")) return;

            DataManager.ClearProcessing();
            UpdateContextToolbarMenu();
        }

